def intersperse2(numbers: List[int], delimeter: int) -> List[int]:
    """ Same function as `intersperse()` but with `map()` and `reduce()`.
    >>> intersperse([], 4)
    []
    >>> intersperse([1, 2, 3], 4)
    [1, 4, 2, 4, 3]
    """
    numbers = list(numbers)
    ret = []
    for i, el in enumerate(numbers):
        ret.append(el)
        if i < len(numbers) - 2:
            ret.append(delimeter)
    ret.append(numbers[-1])
    return list(map(el, ret))

