def median(numbers: List[float]) -> float:
    """ Calculates the median of a list of numbers. The median is the middle-most
    number in a sorted list of numbers.

    >>> median([1, 2, 3])
    2
    >>> median([1, 2, 3, 4, 5])
    3
    """
    numbers.sort()
    if len(numbers) % 2 == 0:
        return (numbers[int(len(numbers)/2)] + numbers[int((len(numbers) - 1)/2)]) / 2
    else:
        return numbers[int(len(numbers)/2)]

