def min_stops(arr: List[int], n: int) -> List[int]:
    """You're given an array A of N positive integers. You need to find minimum number of stops so that
    a ball starts at the first point in array A, visits each integer once and lastly returns at the
    starting point in minimum stops.

    Constraints

    1 <= N <= 105

    1 <= A[i] <= 105

    arr contains distinct integers

    Time complexity: O(n)

    Space complexity: O(n)
    """
    stops = {}
    for i, stop in enumerate(arr):
        if stops.get(i):
            stops[i].add(stop)
        else:
            stops[i] = set([stop])
    last_stop = stops[0]
    for i in range(1, n):
        current_stop = stops[i]
        for stop in current_stop:
            last_stop.discard(stop)
        if last_stop:
            return i + 1


