def standard_deviation(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Standard Deviation
    around the mean of this dataset.
    Standard Deviation is the square root of the variance around the mean
    of this dataset.
    >>> standard_deviation([1.0, 2.0, 3.0, 4.0])
    1.4142135623730951
    >>> standard_deviation([2.0, 5.0, 6.0, 4.0, 3.0, 1.0])
    1.9833457939164473
    """
    squared_list: List[float] = []
    for item in numbers:
        squared_list.append((item - sum(numbers) / len(numbers)) ** 2)
    return sum(squared_list) ** 0.5 / len(numbers)


